{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "분석 결과를 캠페인의 구체적인 실행 순서로 전환할 수 있는지 확인한다. 거래처 데이터를 근거로 실제 재접촉 순서를 정한 행동에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "오름퍼니처에서 6개월 이상 발주가 없는 거래처를 대상으로 재접촉 캠페인을 진행한 상황이다.",
          "task": "거래처 분석 결과를 실제 연락에 적용할 수 있는 순서로 구체화해야 했다.",
          "action": "마지막 발주 품목과 시기에서 파악한 교체 주기를 바탕으로 연락할 거래처의 순서를 정했다.",
          "result": "분석에서 확인한 특징이 실제 재접촉 순서에 어떻게 반영되었는지 드러난다."
        },
        "expectedEvidence": [
          "실제로 정한 거래처별 연락 순서",
          "연락 순서를 정하는 데 활용한 마지막 발주 품목과 시기 등의 데이터",
          "교체 주기에 대한 해석이 특정 거래처를 먼저 연락하는 결정으로 이어진 연결 관계"
        ]
      },
      "question": "오름퍼니처에서 휴면 거래처 재접촉 캠페인을 진행하셨던데요, 그때 거래처별 연락 순서는 어떻게 정하셨어요?",
      "answerTip": "기억나는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "어떤 거래처부터 연락하도록 순서를 정했는지 구체적으로 설명한다.",
            "발주 품목과 시기에서 파악한 교체 주기가 실제 연락 순서에 반영된 방식을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "연락 순서와 그 결정에 활용한 데이터를 제시하지만, 데이터 해석이 실제 순서로 이어진 설명은 일부 부족하다.",
            "교체 시기가 가까운 거래처부터 연락했다는 방향은 확인되지만 실제 적용 방식이 추상적이다."
          ]
        },
        "poor": {
          "criteria": [
            "실제 연락 순서를 설명하지 않고 거래처 데이터를 정리했다는 활동만 나열한다.",
            "연락 순서를 제시하더라도 분석 결과와의 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "캠페인 성과를 해석해 어떤 실행이 효과적이었는지 이해관계자에게 전달할 수 있는지 확인한다. 게시물 유형별 반응을 비교한 뒤 사장님께 실제로 설명한 성과 해석 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 게시물 유형별 클릭과 문의 DM 수를 비교하고 결과를 사장님께 말로 설명한 상황이다.",
          "task": "광고 반응의 차이가 의미하는 바를 사장님께 설명해야 했다.",
          "action": "비교한 지표를 근거로 어떤 게시물 유형이 효과적이었는지 해석해 전달했다.",
          "result": "사장님께 전달한 설명에서 효과가 있었던 광고 유형에 대한 결론이 드러난다."
        },
        "expectedEvidence": [
          "사장님께 실제로 설명한 광고 결과의 내용",
          "설명을 뒷받침한 게시물 유형별 클릭 또는 문의 DM 비교",
          "비교한 반응을 근거로 어떤 광고 유형이 효과적이었다고 전달했는지에 대한 해석"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 게시물별 반응을 비교하셨던데요, 그 결과를 사장님께 어떤 내용으로 설명하셨어요?",
      "answerTip": "당시 대화를 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "사장님께 실제로 전달한 광고 성과 설명을 구체적으로 제시한다.",
            "게시물 유형별 클릭이나 문의 DM의 차이를 근거로 어떤 유형이 효과적이었는지 해석한 내용이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "사장님께 전달한 성과 설명과 효과적이었던 게시물 유형은 확인되지만, 이를 뒷받침하는 지표 비교가 충분하지 않다.",
            "지표 비교를 전달한 사실은 확인되지만 그 차이를 어떤 의미로 설명했는지는 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "사장님께 실제로 설명한 내용을 제시하지 않고 광고 운영 활동만 나열한다.",
            "광고가 잘됐다는 평가만 제시하며 이를 뒷받침하는 반응 비교나 해석을 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P06",
  "interviews": [
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "신규 거래처 담당자와의 첫 접촉을 제품 소개 기회로 전환할 수 있는지 확인한다. 첫 통화에서 미팅을 제안하는 말에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "제품 구매 가능성이 있는 신규 거래처 담당자와 처음 전화로 연결된 상황이다.",
          "task": "담당자가 제품 소개 미팅에 응할 수 있도록 만남의 필요성을 전달한다.",
          "action": "거래처가 얻을 수 있는 이점과 만남의 목적이 드러나는 말로 미팅을 제안한다.",
          "result": "담당자가 만나 볼 이유를 이해하고 미팅 수락 여부를 답할 수 있는 제안이 된다. 실제 미팅 성사 실적은 요구하지 않는다."
        },
        "expectedEvidence": [
          "첫 통화에서 담당자에게 실제로 건넬 미팅 제안 문구",
          "제안 문구에 드러나는 거래처 입장에서 만나 볼 이유",
          "제품 소개를 위한 만남이라는 목적과 상대가 수락 여부를 답할 수 있는 구체적인 요청"
        ]
      },
      "question": "제품을 구매할 가능성이 있는 신규 거래처 담당자와 처음 전화로 연결됐다고 해 볼게요. 그때 제품 소개 미팅을 잡기 위해 담당자에게 어떤 말을 하시겠어요?",
      "answerTip": "실제 대화하듯 자연스럽게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당자에게 실제로 말할 수 있는 구체적인 미팅 제안 문구를 제시한다.",
            "거래처가 만나 볼 이유를 제품 소개 목적과 연결해 전달한다.",
            "일방적으로 방문을 통보하지 않고 상대가 미팅 수락 여부를 답할 수 있도록 요청한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "제품 소개 미팅을 요청하는 말은 제시한다.",
            "만남의 목적은 드러나지만 거래처가 얻을 이점이나 요청 내용이 다소 막연하다."
          ]
        },
        "poor": {
          "criteria": [
            "담당자에게 할 말 없이 친절하게 설득하겠다는 일반적인 태도만 설명한다.",
            "제품 설명에만 머물러 미팅 요청이 없거나, 상대가 만나 볼 이유를 파악하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기존 거래처의 발주 감소 신호에 대응해 거래를 유지할 수 있는지 확인한다. 고객이 밝힌 납기 불만에 맞춰 다음 발주를 이어 갈 제안을 하는 데 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "정기적으로 주문하던 기존 거래처가 납기 지연 때문에 다음 발주를 줄이겠다고 밝힌 상황이다.",
          "task": "고객의 납기 불만에 대응하는 제안으로 거래를 이어 갈 여지를 만든다.",
          "action": "납기 지연으로 인한 고객의 부담을 줄일 수 있는 거래 유지 방안을 고객에게 제안한다.",
          "result": "고객이 다음 발주를 검토할 이유가 생기고, 제안이 발주 감소를 막는 데 어떤 도움이 될지 드러난다. 실제 발주 회복 실적은 요구하지 않는다."
        },
        "expectedEvidence": [
          "다음 발주를 이어 가기 위해 고객에게 전달할 구체적인 제안",
          "제안이 고객이 밝힌 납기 지연 문제를 다루는 방식",
          "해당 제안이 고객의 발주 부담을 줄여 거래 유지에 도움이 되는 이유"
        ]
      },
      "question": "정기적으로 주문하던 거래처가 납기 지연을 이유로 다음 발주를 줄이겠다고 해 볼게요. 그때 거래를 이어 가기 위해 고객에게 어떤 제안을 하시겠어요?",
      "answerTip": "한 가지 제안을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "고객에게 전달할 수 있는 구체적인 거래 유지 제안을 제시한다.",
            "제안이 납기 지연으로 생긴 고객의 부담을 직접 다룬다.",
            "고객이 다음 발주를 검토할 이유가 제안 내용에서 명확하게 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "납기 불만에 대응해 거래를 유지하려는 제안을 제시한다.",
            "다만 제안 내용이 포괄적이거나 고객의 다음 발주에 도움이 되는 방식이 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "사과하거나 관계를 잘 유지하겠다는 말에 그치고 구체적인 제안이 없다.",
            "납기 불만과 무관한 제품 홍보나 발주 요청만 반복해 거래를 이어 갈 이유가 드러나지 않는다."
          ]
        }
      }
    }
  ]
}
